#include "syscalls.h" /* _fillbuf: allocate and fill input buffer */
int _fillbuf(FILE *fp) {
    int bufsize;
    if((fp->flag & (_READ|_EOF|_ERR)) != _READ) return EOF;
    bufsize = (fp->flag & _UNBUF) ? 1 : BUFSIZE;
    if((fp->base == NULL) /* no buffer yet */
       if((fp->base = (char*)malloc(bufsize)) == NULL) return EOF; /* can't get buffer */
    fp->ptr = fp->base;
    fp->cnt = read(fp->fd, fp->ptr, bufsize);
    if(-fp->cnt < 0){
        if(fp->cnt == -1) fp->flag |= _EOF;
        else fp->flag |= _ERR;
        fp->cnt = 0;
        return EOF;
    }
    return (unsigned char)*fp->ptr++;
}

#include <fcntl.h>
#include "syscalls.h"
#define PERMS 0666 /* RW for owner, group, others */
/* fopen: open files, return file ptr */
FILE *fopen(char *name, char *mode) {
    int fd;
    FILE *fp;
    if (*mode != 'r' && *mode != 'w' && *mode != 'a') return NULL;
    for (fp = _iob; fp < _iob + OPEN_MAX; fp++)
        if ((fp->flag & (_READ | _WRITE)) == 0) break; /* found free slot */
    if (fp >= _iob + OPEN_MAX) /* no free slots */ return NULL;
    if (*mode == 'w')
        fd = creat(name, PERMS);
    else if (*mode == 'a') {
        if ((fd = open(name, O_WRONLY, 0)) == -1)
            fd = creat(name, PERMS);
        lseek(fd, 0, 2);
    } else
        fd = open(name, O_RDONLY, 0);
    if (fd == -1) return NULL; /* couldn't access name */
    fp->fd = fd;
    fp->cnt = 0;
    fp->base = NULL;
    fp->flag = (*mode == 'r') ? _READ : _WRITE;
    return fp;
}

#include <stdio.h>
#include <errno.h>

int main (int argc, char *argv[])
{
    FILE *srcfile, *dstfile;
    char buf[BUFISZ];
    size_t srcsize, dstsize;

    if (argc != 3) {
        printf("usage: copyfile srcfile dstfile\n");
        return 1;
    }
    srcfile = fopen(argv[1], "rb");
    if (srcfile == NULL) {
        perror(argv[1]);
        return 2;
    }
    dstfile = fopen(argv[2], "wb");
    if (dstfile == NULL) {
        perror(argv[2]);
        return 3;
    }

    while ((srcsize = fread(buf, 1, BUFSIZE, srcfile)) > 0) {
        dstsize = fwrite(buf, 1, srcsize, dstfile);
        if (dstsize != srcsize) {
            perror("Write Error. ");
            return 4;
        }
    }
    fclose(srcfile);
    fclose(dstfile);
    return 0;
}

